{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.BUILDSKILL_DB_PRODUCT_MARKETING_CONSOLIDATED AS WITH sku_map AS ( SELECT * FROM `maplemonk.Buildskill_GS_SKU_MASTER` QUALIFY ROW_NUMBER() OVER (PARTITION BY master_sku) = 1 ), marketing_consolidated AS ( SELECT LOWER(TRIM(channel)) AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.buildskill_wh_MARKETING_CONSOLIDATED` GROUP BY 1,2 ), amazon_channel_spend AS ( SELECT LOWER(\'amazon\') AS channel, DATE(date) AS date, SUM(CAST(spend AS FLOAT64)) AS total_channel_spend FROM `maplemonk.Buildskill_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` GROUP BY 1,2 ), amazon AS ( SELECT CAST(NULL AS STRING) AS ADSET_NAME, CAST(NULL AS STRING) AS ADSET_ID, CAST(a.AD_ID AS STRING) AS AD_ID, CAST(a.ADGROUPNAME AS STRING) AS AD_NAME, CAST(a.PROFILENAME AS STRING) AS ACCOUNT_NAME, CAST(a.PROFILEID AS STRING) AS ACCOUNT_ID, CAST(a.CAMPAIGNNAME AS STRING) AS CAMPAIGN_NAME, CAST(a.CAMPAIGN_ID AS STRING) AS CAMPAIGN_ID, CAST(a.channel_product_id AS STRING) AS PRODUCT_ID, CAST(NULL AS STRING) AS VARIANT_ID, a.DATE AS DATE, CAST(a.AD_TYPE_1 AS STRING) AS AD_TYPE, CAST(NULL AS STRING) AS AD_STRENGTH, CAST(NULL AS STRING) AS AD_NETWORK_TYPE, CAST(NULL AS STRING) AS AD_FINAL_URL, FORMAT_DATE(\'%A\', a.DATE) AS DAY_OF_WEEK, EXTRACT(YEAR FROM a.DATE) AS YEAR, EXTRACT(MONTH FROM a.DATE) AS MONTH, CAST(\'Amazon\' AS STRING) AS CHANNEL, CAST(a.PROFILENAME AS STRING) AS ACCOUNT, a.clicks AS CLICKS, a.spend AS SPEND, a.impressions AS IMPRESSIONS, a.conversions AS CONVERSIONS, ifnull(a.conversion_value, 0) AS CONVERSION_VALUE, ifnull(a.conversion_value, 0) AS SALES, UPPER(TRIM(sm.master_sku)) AS SKU, UPPER(TRIM(sm.PRODUCT_TITLE)) as product_name, CONCAT(upper(trim(CATEGORY)), \'-\', upper(trim(SUB_CATEGORY))) AS master_category FROM ( SELECT AD_ID, ADGROUPNAME, PROFILEID, CAMPAIGNNAME, CAMPAIGN_ID, profileName, COALESCE( CASE WHEN LENGTH(TRIM(asin)) = 10 THEN TRIM(asin) END, CASE WHEN LENGTH(TRIM(SPLIT(campaignname, \'-\')[SAFE_OFFSET(2)])) = 10 THEN TRIM(SPLIT(campaignname, \'-\')[SAFE_OFFSET(2)]) END) AS channel_product_id, DATE(Date) AS DATE, AD_TYPE_1, SUM(clicks) clicks, SUM(spend) spend, SUM(Impressions) impressions, SUM(ATTRIBUTED_CONVERSIONS_14D) conversions, SUM(ATTRIBUTED_SALES_14D) conversion_value FROM `maplemonk.Buildskill_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` WHERE channel_product_id IS NOT NULL GROUP BY 1,2,3,4,5,6,7,8,9 ) a LEFT JOIN sku_map sm ON TRIM(LOWER(CAST(a.channel_product_id AS STRING))) = TRIM(LOWER(CAST(sm.ASIN AS STRING))) ), marketing_consolidated_product_intermediate AS ( SELECT * FROM amazon ) SELECT m.*, IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS total_product_lvl_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%amazon%\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END, 0) AS total_channel_spend, IFNULL(CASE WHEN LOWER(m.channel) LIKE \'%amazon%\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END, 0) - IFNULL(SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL), 0) AS spend_diff, CASE WHEN (CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) > SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL) AND SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL) > 0 THEN ((CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.conversion_value / SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL)) ELSE 0 END AS allocated_spend_diff, CASE WHEN (CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) > SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL) AND SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL) > 0 THEN m.SPEND + (((CASE WHEN LOWER(m.channel) = \'amazon\' THEN ac.total_channel_spend ELSE mc.total_channel_spend END) - SUM(m.SPEND) OVER (PARTITION BY m.DATE, m.CHANNEL)) * (m.conversion_value / SUM(m.conversion_value) OVER (PARTITION BY m.DATE, m.CHANNEL))) ELSE m.SPEND END AS corrected_spend FROM marketing_consolidated_product_intermediate m LEFT JOIN marketing_consolidated mc ON LOWER(TRIM(CAST(m.channel AS STRING))) = LOWER(TRIM(CAST(mc.channel AS STRING))) AND CAST(m.date AS DATE) = CAST(mc.date AS DATE) LEFT JOIN amazon_channel_spend ac ON LOWER(TRIM(CAST(m.channel AS STRING))) = LOWER(TRIM(CAST(ac.channel AS STRING))) AND CAST(m.date AS DATE) = CAST(ac.date AS DATE) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
